test('popup focus returns to its original trigger across chooser/details and cleans up its watcher',async()=>{
 const {PlacePopupFocus}=load('PlacePopupFocus'),old=global.document;const body={},trigger={isConnected:true,hasAttribute:()=>false,getClientRects:()=>[{}],focus(){global.document.activeElement=this;}};let changes,removed=0,focused=0,options;
 global.document={body,activeElement:trigger};const popup={visible:true,content:null,container:{},watch(keys,callback){changes=callback;return{remove(){removed++;}}}},view={popup,container:{},openPopup(o){options=o;popup.content=o.content;popup.visible=true;global.document.activeElement={parentNode:o.content};},focus(){focused++;}};
 try{
  const focus=new PlacePopupFocus(),chooser={};focus.open(view,{content:chooser},focus.capture(view));await flush();assert.equal(options.shouldFocus,true);assert.equal(focus.capture(view),trigger);
  const origin=focus.capture(view),details={};focus.open(view,{content:details},origin);await flush();assert.equal(removed,1);popup.visible=false;changes();assert.equal(global.document.activeElement,trigger);assert.equal(removed,2);assert.equal(focused,0);
  focus.open(view,{content:{}},trigger);await flush();trigger.isConnected=false;popup.visible=false;changes();assert.equal(focused,1);focus.cancel();assert.equal(removed,3);
 }finally{global.document=old;}
});
test('popup focus never steals focus from another control, replacement popup or cancelled open',async()=>{
 const {PlacePopupFocus}=load('PlacePopupFocus'),old=global.document;let changes,removed=0,restored=0,resolve;
 const body={},trigger={isConnected:true,hasAttribute:()=>false,getClientRects:()=>[{}],focus(){restored++;}},popup={visible:true,content:null,watch(keys,callback){changes=callback;return{remove(){removed++;}}}},view={popup,focus(){restored++;},openPopup(o){popup.content=o.content;popup.visible=true;}};global.document={body,activeElement:trigger};
 try{
  const focus=new PlacePopupFocus();focus.open(view,{content:{}},trigger);await flush();global.document.activeElement={};popup.visible=false;changes();assert.equal(restored,0);assert.equal(removed,1);
  focus.open(view,{content:{}},trigger);await flush();global.document.activeElement=body;popup.content={};changes();assert.equal(restored,0);assert.equal(removed,2);
  view.openPopup=o=>new Promise(r=>{popup.content=o.content;resolve=r;});focus.open(view,{content:{}},trigger);focus.cancel();resolve();await flush();assert.equal(removed,2);assert.equal(restored,0);
 }finally{global.document=old;}
});
